//! Outbound mail submission shapes.

use std::collections::BTreeSet;

use engine_core::{
    ids::{MessageIdHeader, ProviderKey},
    mail::{EmailAddress, Keyword},
    scheduling::ScheduleMethod,
};
use serde::{Deserialize, Serialize};

// The attachment shapes moved beside this module for the file-length budget
// (a pure move): these re-exports keep every existing path working.
pub use crate::draft_attachment::{
    ContentIdError, ContentIdHeader, DraftAttachment, DraftAttachmentDisposition,
};

/// A mail message to send.
///
/// The `message_id` is generated by the caller **before** submission (the Write
/// Contract: a stable `Message-ID` precedes the send), so the sent copy can be
/// reconciled by `Message-ID` when it later syncs back (`store-and-sync.md`).
/// The body always carries a plain-text fallback and may add an HTML alternative
/// plus inline or regular attachments. Serializable so a caller can store it as a
/// durable outbox `PendingOp` payload before sending.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Draft {
    /// The pre-generated `Message-ID` header value (no angle brackets).
    pub message_id: MessageIdHeader,
    /// The sender address.
    pub from: EmailAddress,
    /// The recipient addresses.
    pub to: Vec<EmailAddress>,
    /// The `Cc` ("carbon copy") recipients — visible to every recipient. Empty for
    /// none. Defaulted so a payload serialized before Cc/Bcc support still deserializes.
    #[serde(default)]
    pub cc: Vec<EmailAddress>,
    /// The `Bcc` ("blind carbon copy") recipients. They are delivered to (added to the
    /// SMTP envelope) but, by convention, **never** written as a message header, so no
    /// other recipient can see them. Empty for none. Defaulted for back-compat like `cc`.
    #[serde(default)]
    pub bcc: Vec<EmailAddress>,
    /// The subject.
    pub subject: String,
    /// The plain-text body.
    pub text_body: String,
    /// The optional HTML alternative body.
    #[serde(default)]
    pub html_body: Option<String>,
    /// Inline and regular draft attachments.
    #[serde(default)]
    pub attachments: Vec<DraftAttachment>,
    /// An iTIP scheduling object to carry as a **body part** (iMIP, RFC 6047).
    ///
    /// `None` for an ordinary message. Defaulted so a payload serialized before iMIP
    /// support still deserializes. See [`DraftCalendar`] for why this is not an attachment.
    #[serde(default)]
    pub calendar: Option<DraftCalendar>,
    /// The `Message-ID` this message replies to, if any — the RFC 5322 §3.6.4
    /// `In-Reply-To` value (the parent's `Message-ID`, no angle brackets). `None`
    /// for an original (non-reply) message. Defaulted so a payload serialized
    /// before threading support still deserializes.
    #[serde(default)]
    pub in_reply_to: Option<MessageIdHeader>,
    /// The RFC 5322 §3.6.4 `References` chain that threads this message with its
    /// original: the parent's `References` followed by the parent's own
    /// `Message-ID`, oldest first (each value with no angle brackets). Empty for an
    /// original (non-reply) message. Defaulted for back-compat like `in_reply_to`.
    #[serde(default)]
    pub references: Vec<MessageIdHeader>,
    /// Keywords to set on the **sender's filed copy** in Sent, never on what the recipients
    /// receive: a keyword is mailbox state, not a header.
    ///
    /// A request, not a promise. An adapter that cannot store them files the copy without
    /// them and says so in [`SubmissionReceipt::sent_copy_keywords`]; the send never fails
    /// over a keyword. Whether an adapter tries at all is
    /// [`Capabilities::sent_copy_keywords`](crate::Capabilities::sent_copy_keywords).
    /// Defaulted so a payload serialized before this field still deserializes.
    #[serde(default)]
    pub sent_copy_keywords: BTreeSet<Keyword>,
    /// Asks the account's installed MIME wrapper to sign the message on the way
    /// out. Inert when no wrapper is installed; the wrapper decides what
    /// "sign" means for the account. Defaulted so a payload serialized before
    /// crypto support still deserializes.
    #[serde(default)]
    pub sign: bool,
    /// Asks the installed MIME wrapper to encrypt the message on the way out.
    /// Inert when no wrapper is installed; defaulted for back-compat like
    /// `sign`.
    #[serde(default)]
    pub encrypt: bool,
}

impl Draft {
    /// Assembles a draft to send.
    ///
    /// The threading linkage defaults to none; set it with the
    /// [`in_reply_to`](Draft::in_reply_to) builder for a reply or forward.
    #[must_use]
    pub fn new(
        message_id: MessageIdHeader,
        from: EmailAddress,
        to: Vec<EmailAddress>,
        subject: impl Into<String>,
        text_body: impl Into<String>,
    ) -> Self {
        Self {
            message_id,
            from,
            to,
            cc: Vec::new(),
            bcc: Vec::new(),
            subject: subject.into(),
            text_body: text_body.into(),
            html_body: None,
            attachments: Vec::new(),
            calendar: None,
            in_reply_to: None,
            references: Vec::new(),
            sent_copy_keywords: BTreeSet::new(),
            sign: false,
            encrypt: false,
        }
    }

    /// Sets the `Cc` recipients (visible to every recipient).
    #[must_use]
    pub fn with_cc(mut self, cc: Vec<EmailAddress>) -> Self {
        self.cc = cc;
        self
    }

    /// Sets the `Bcc` recipients — delivered via the SMTP envelope but never emitted as
    /// a header, so they stay hidden from every other recipient.
    #[must_use]
    pub fn with_bcc(mut self, bcc: Vec<EmailAddress>) -> Self {
        self.bcc = bcc;
        self
    }

    /// Sets the threading linkage for a **reply**: the `parent` message's `Message-ID`
    /// (the RFC 5322 §3.6.4 `In-Reply-To`) and the full `references` chain (the parent's
    /// `References` plus its own `Message-ID`, oldest first). The assembler emits both so
    /// the sent message threads with its original.
    ///
    /// A forward is not a reply — use [`with_references`](Self::with_references), which
    /// threads it without claiming it answers anything.
    #[must_use]
    pub fn in_reply_to(
        mut self,
        parent: MessageIdHeader,
        references: Vec<MessageIdHeader>,
    ) -> Self {
        self.in_reply_to = Some(parent);
        self.references = references;
        self
    }

    /// Sets the `References` chain (RFC 5322 §3.6.4) **without** an `In-Reply-To` — the
    /// linkage a **forward** carries.
    ///
    /// A forward continues a conversation but does not answer a message, so it takes the
    /// chain and not the reply pointer. That is enough to thread it: RFC 5256 threading,
    /// this engine's own derivation, and every mainstream client all unite on `References`
    /// alone.
    #[must_use]
    pub fn with_references(mut self, references: Vec<MessageIdHeader>) -> Self {
        self.references = references;
        self
    }

    /// Adds an HTML alternative body.
    #[must_use]
    pub fn with_html_body(mut self, html_body: impl Into<String>) -> Self {
        self.html_body = Some(html_body.into());
        self
    }

    /// Clears the HTML alternative body.
    #[must_use]
    pub fn without_html_body(mut self) -> Self {
        self.html_body = None;
        self
    }

    /// Adds an inline or regular attachment.
    #[must_use]
    pub fn with_attachment(mut self, attachment: DraftAttachment) -> Self {
        self.attachments.push(attachment);
        self
    }

    /// Carries an iTIP object as an alternative body part, making this an iMIP message
    /// (RFC 6047) — the way an answer reaches an organizer when the calendar server will
    /// not send it
    /// ([`Capabilities::calendar_scheduling`](crate::Capabilities::calendar_scheduling)).
    #[must_use]
    pub fn with_calendar(mut self, calendar: DraftCalendar) -> Self {
        self.calendar = Some(calendar);
        self
    }

    /// Asks for `keyword` on the sender's filed copy ([`Self::sent_copy_keywords`]).
    #[must_use]
    pub fn with_sent_copy_keyword(mut self, keyword: Keyword) -> Self {
        self.sent_copy_keywords.insert(keyword);
        self
    }

    /// Asks the installed MIME wrapper to sign and/or encrypt this draft on the
    /// way out ([`Self::sign`], [`Self::encrypt`]). The wrapper is consulted
    /// only when one is set; both default to `false` (send plainly).
    #[must_use]
    pub fn with_crypto(mut self, sign: bool, encrypt: bool) -> Self {
        self.sign = sign;
        self.encrypt = encrypt;
        self
    }
}

/// An iTIP scheduling object carried as an **alternative body part** (iMIP, RFC 6047 §2.4).
///
/// Not a [`DraftAttachment`], and the difference is what makes the message work. An
/// attachment part carries a `Content-Disposition` and a file name — it is a document the
/// message *encloses*. An iTIP object is a **representation of the message itself**: a
/// sibling of the text body inside `multipart/alternative`, whose `Content-Type` carries
/// the `method=` parameter RFC 6047 §2.4 requires and which receiving clients dispatch on.
/// A `DraftAttachment` cannot express that parameter at all, so an answer sent as one is
/// filed as `invite.ics` and never processed as a reply.
///
/// The text body stays load-bearing: RFC 6047 §2.4 says a scheduling message SHOULD carry a
/// human-readable alternative, for the recipients whose client does not understand
/// `text/calendar`. A caller supplies it as [`Draft::text_body`] — "Accepted: Sprint
/// planning" — exactly as for any other message.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DraftCalendar {
    /// The serialized iCalendar object, `BEGIN:VCALENDAR` … `END:VCALENDAR`.
    pub ical: String,
    /// The scheduling method, which becomes the `method=` `Content-Type` parameter.
    ///
    /// RFC 6047 §2.4 requires it to equal (ignoring case) the `METHOD` property **inside**
    /// `ical`. The assembler emits what it is given rather than re-parsing the object to
    /// check, so a caller that builds the two from one value cannot get them apart; one
    /// that does not, can.
    pub method: ScheduleMethod,
}

impl DraftCalendar {
    /// An iTIP object to carry as a body part, with the `METHOD` it declares.
    #[must_use]
    pub fn new(method: ScheduleMethod, ical: impl Into<String>) -> Self {
        Self {
            ical: ical.into(),
            method,
        }
    }
}

/// What became of the sender's own copy of a delivered message.
///
/// Delivering and filing are **one step on most transports and two on IMAP**: JMAP files the
/// copy with the submission's `onSuccessUpdateEmail`, Graph and Gmail file it server-side, and
/// an IMAP/SMTP account is delivered over SMTP and then filed by us with a separate `APPEND`.
/// A two-step transport can therefore deliver a message and still fail to file it, and that
/// outcome belongs to the caller: the mail has reached its recipients and must never be
/// re-sent, yet the sender's Sent folder is missing it and no later sync will notice — there
/// is nothing on the server left to reconcile against.
///
/// Every adapter states which of the two it achieved, because a receipt that *cannot* express
/// "delivered but not filed" is what let a lost Sent copy read as a clean send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SentCopy {
    /// Filed in the account's Sent folder; [`SubmissionReceipt::email_key`] addresses it.
    Filed,
    /// Delivered to its recipients, but the sender's copy was **not** filed.
    Unfiled {
        /// Why filing failed — a failure class and protocol detail, for a log line and a
        /// host-visible hint. Never draft content or addresses.
        detail: String,
    },
}

impl SentCopy {
    /// Whether the sender's copy reached their Sent folder.
    #[must_use]
    pub fn is_filed(&self) -> bool {
        matches!(self, Self::Filed)
    }

    /// Why filing failed, or `None` when it did not fail.
    #[must_use]
    pub fn unfiled_detail(&self) -> Option<&str> {
        match self {
            Self::Filed => None,
            Self::Unfiled { detail } => Some(detail),
        }
    }
}

/// The result of a successful submission — the message reached its recipients.
///
/// Whether the *sender's* copy also reached their Sent folder is a separate question with a
/// separate answer: [`Self::sent_copy`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SubmissionReceipt {
    /// The provider key of the sent message (filed in Sent), for the outbox to
    /// record as the op's resolved key.
    pub email_key: ProviderKey,
    /// The `Message-ID` that was sent, echoed for sync-time reconciliation.
    pub message_id: MessageIdHeader,
    /// What became of the sender's own copy.
    pub sent_copy: SentCopy,
    /// Which of the draft's [`Draft::sent_copy_keywords`] the filed copy carries.
    ///
    /// Empty when the draft asked for none, when the copy was not filed, and when the
    /// adapter or the server could not keep them. A keyword the draft asked for and this
    /// set lacks was **not** stored; the send itself is unaffected.
    pub sent_copy_keywords: BTreeSet<Keyword>,
}

impl SubmissionReceipt {
    /// Records a submission whose sent copy **was** filed in the account's Sent folder.
    ///
    /// `handed_over` is the proof the attempt recorded its hand-over ([`HandOver`]): a
    /// receipt says a message was delivered, and none can be made by an attempt that never
    /// recorded it might be.
    ///
    /// [`HandOver`]: crate::HandOver
    #[must_use]
    pub fn filed(
        email_key: ProviderKey,
        message_id: MessageIdHeader,
        handed_over: &crate::HandedOver,
    ) -> Self {
        let _ = handed_over;
        Self {
            email_key,
            message_id,
            sent_copy: SentCopy::Filed,
            sent_copy_keywords: BTreeSet::new(),
        }
    }

    /// Records a submission that was **delivered but whose sent copy was not filed**, with
    /// `detail` explaining why. The message is still sent: a caller surfaces this, and never
    /// retries the submission. `handed_over` as for [`filed`](Self::filed).
    #[must_use]
    pub fn unfiled(
        email_key: ProviderKey,
        message_id: MessageIdHeader,
        detail: impl Into<String>,
        handed_over: &crate::HandedOver,
    ) -> Self {
        let _ = handed_over;
        Self {
            email_key,
            message_id,
            sent_copy: SentCopy::Unfiled {
                detail: detail.into(),
            },
            sent_copy_keywords: BTreeSet::new(),
        }
    }

    /// Records the keywords the filed copy carries ([`Self::sent_copy_keywords`]).
    #[must_use]
    pub fn with_sent_copy_keywords(mut self, keywords: BTreeSet<Keyword>) -> Self {
        self.sent_copy_keywords = keywords;
        self
    }
}

